import { test, expect } from '@playwright/test';

test.describe('Image Paste from Clipboard to Upload Area', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should successfully paste an image from clipboard into upload area', async ({ page }) => {
    // Setup: intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Setup: intercept the file read API
    await page.route('**/api/file/read', (route) => {
      route.continue();
    });

    // Get the upload area by role
    const uploadArea = page.getByRole('region', { name: /upload area/i });
    await expect(uploadArea).toBeVisible();

    // Get the paste button by role
    const pasteButton = page.getByRole('button', { name: /paste/i });
    await expect(pasteButton).toBeVisible();

    // Click the paste button
    await pasteButton.click();

    // Wait for the file to be processed
    await page.waitForTimeout(500);

    // Verify the image preview appears
    const imagePreview = page.getByRole('img', { name: /image preview/i });
    await expect(imagePreview).toBeVisible();

    // Verify the image has a valid source
    const imgSrc = await imagePreview.getAttribute('src');
    expect(imgSrc).toContain('data:image');

    // Verify the upload area shows the file name
    const fileNameDisplay = page.getByText(/image.png/i);
    await expect(fileNameDisplay).toBeVisible();

    // Verify the upload button is enabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeEnabled();
  });

  test('should handle clipboard paste with invalid or unsupported file types', async ({ page }) => {
    // Setup: intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Get the upload area by role
    const uploadArea = page.getByRole('region', { name: /upload area/i });
    await expect(uploadArea).toBeVisible();

    // Get the paste button by role
    const pasteButton = page.getByRole('button', { name: /paste/i });
    await expect(pasteButton).toBeVisible();

    // Click the paste button
    await pasteButton.click();

    // Wait for file processing
    await page.waitForTimeout(500);

    // Verify error message appears for invalid file type
    const errorMessage = page.getByText(/invalid file type/i);
    await expect(errorMessage).toBeVisible();

    // Verify image preview does not appear
    const imagePreview = page.getByRole('img', { name: /image preview/i });
    await expect(imagePreview).not.toBeVisible();

    // Verify upload button remains disabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeDisabled();

    // Verify error message is cleared when user clicks clear
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();
    await expect(errorMessage).not.toBeVisible();
  });
});
